/**
 * Findings as files: a Markdown report, one GitHub issue body per finding, or a SARIF file for
 * GitHub code scanning. Everything here is deterministic text built from what the agents already
 * reported; nothing is generated by a model and nothing is written into the user's project.
 *
 * Findings are raw agent reports, so every piece of free text is treated as untrusted: titles and
 * steps become single lines, descriptions go into block quotes, commands into code fences. A finding
 * can therefore never add headings, links or fake sections to a document.
 */
import type { SentryRepository } from '@qa/persistence';
import {
  FINDING_EXPORT_FORMATS,
  FINDING_EXPORT_MAX_FINDINGS,
  type Evidence,
  type Finding,
  type FindingExportFormat,
  type FindingExportSelection,
} from '@qa/schemas';
import { RunEngineError } from './errors.js';

// The formats, the selection shapes and the 500 finding limit are shared with Desktop and the CLI.
export {
  FINDING_EXPORT_FORMATS,
  FINDING_EXPORT_MAX_FINDINGS,
  type FindingExportFormat,
  type FindingExportSelection,
};

/** The most text one export may produce. */
export const FINDING_EXPORT_MAX_BYTES = 6_000_000;

export interface ExportFile {
  readonly path: string;
  readonly content: string;
}

export interface FindingExportResult {
  readonly format: FindingExportFormat;
  /** One file for Markdown and SARIF; several for GitHub issues (Desktop saves them as a ZIP). */
  readonly files: readonly ExportFile[];
  readonly findingCount: number;
  readonly suggestedName: string;
  readonly mimeType: string;
}

/** A finding with the context an export needs, resolved from the stored records. */
export interface ExportedFinding {
  readonly finding: Finding;
  readonly runId: string;
  readonly revisionId: string | undefined;
  readonly revisionHash: string | undefined;
  readonly evidence: readonly Evidence[];
}

const SEVERITY_ORDER = ['critical', 'high', 'medium', 'low', 'info'] as const;

/** Text that must stay on one line: control characters and runs of whitespace become one space. */
export function oneLine(value: string): string {
  return value.replace(/[\p{Cc}\s]+/gu, ' ').trim();
}

/** A block quote, so free text can never start a heading, list or fence of its own. */
function quote(value: string): string {
  return value
    .split(/\r?\n/)
    .map((line) => (line.trim() === '' ? '>' : '> ' + line.replace(/[\p{Cc}]/gu, ' ')))
    .join('\n');
}

/** Inline code that survives backticks inside the text. */
function inlineCode(value: string): string {
  const text = oneLine(value);
  const longest = Math.max(0, ...(text.match(/`+/g) ?? []).map((run) => run.length));
  const ticks = '`'.repeat(longest + 1);
  return ticks + (text.startsWith('`') || text.endsWith('`') ? ' ' + text + ' ' : text) + ticks;
}

function shortHash(hash: string | undefined): string {
  if (hash === undefined) return 'unknown';
  const digits = hash.replace(/^sha256:/, '');
  return digits.length <= 6 ? digits : digits.slice(0, 3) + '...' + digits.slice(-3);
}

function locationText(finding: Finding): string[] {
  return finding.locations.map((location) => {
    const lines =
      location.startLine === undefined
        ? ''
        : ':' +
          location.startLine +
          (location.endLine === undefined || location.endLine === location.startLine
            ? ''
            : '-' + location.endLine);
    return (
      '- ' +
      inlineCode(location.relativePath + lines) +
      (location.symbol === undefined ? '' : ' (' + inlineCode(location.symbol) + ')')
    );
  });
}

function evidenceLines(items: readonly Evidence[]): string[] {
  return items.map((item) => {
    const base = '- ' + item.strength.replace(/_/g, ' ');
    const description = item.description === undefined ? '' : ': ' + oneLine(item.description);
    const command =
      item.type === 'command'
        ? ' (ran ' + inlineCode(item.command.command) + ', exit code ' + item.command.exitCode + ')'
        : '';
    return base + description + command;
  });
}

/** One finding as a Markdown section body (everything after its heading). */
function findingBody(entry: ExportedFinding): string[] {
  const { finding } = entry;
  const lines: string[] = [];
  lines.push(
    '- Severity: **' +
      finding.severity +
      '**, confidence: ' +
      finding.confidence +
      ', category: ' +
      finding.category +
      (finding.categoryDetail === undefined ? '' : ' (' + oneLine(finding.categoryDetail) + ')'),
  );
  lines.push(
    '- Reported by ' +
      inlineCode(finding.sourceAgentStackId) +
      ' in run ' +
      inlineCode(entry.runId) +
      ', revision ' +
      inlineCode(entry.revisionId ?? 'unknown') +
      ' (' +
      shortHash(entry.revisionHash) +
      ')',
  );
  lines.push('- Finding ID: ' + inlineCode(finding.id));
  lines.push('', '**Where**', '', ...locationText(finding));
  lines.push('', '**Description**', '', quote(finding.description));
  const optional: Array<[string, string | undefined]> = [
    ['Expected behavior', finding.expectedBehavior],
    ['Actual behavior', finding.actualBehavior],
    ['Root cause', finding.rootCause],
    ['Recommended fix', finding.recommendedFix],
  ];
  for (const [label, value] of optional)
    if (value !== undefined) lines.push('', '**' + label + '**', '', quote(value));
  if (finding.reproductionSteps.length > 0) {
    lines.push('', '**Reproduction steps**', '');
    finding.reproductionSteps.forEach((step, index) =>
      lines.push(index + 1 + '. ' + oneLine(step)),
    );
  }
  if (entry.evidence.length > 0)
    lines.push('', '**Evidence**', '', ...evidenceLines(entry.evidence));
  return lines;
}

function severityCounts(entries: readonly ExportedFinding[]): string {
  return SEVERITY_ORDER.map((severity) => ({
    severity,
    count: entries.filter((entry) => entry.finding.severity === severity).length,
  }))
    .filter((item) => item.count > 0)
    .map((item) => item.count + ' ' + item.severity)
    .join(', ');
}

const REVIEW_NOTE =
  'These are reports written by AI agents. They are not merged or de-duplicated, and each one should be reviewed before anyone acts on it.';

export function markdownReport(input: {
  readonly projectName: string;
  readonly entries: readonly ExportedFinding[];
  readonly generatedAt: string;
}): string {
  const { entries } = input;
  const revisions = [
    ...new Set(
      entries.map(
        (entry) => (entry.revisionId ?? 'unknown') + ' (' + shortHash(entry.revisionHash) + ')',
      ),
    ),
  ];
  const lines: string[] = [
    '# Sentry findings report',
    '',
    '- Project: ' + oneLine(input.projectName),
    '- Generated: ' + input.generatedAt,
    '- Findings: ' +
      entries.length +
      (entries.length === 0 ? '' : ' (' + severityCounts(entries) + ')'),
    '- Revisions: ' + (revisions.length === 0 ? 'none' : revisions.join(', ')),
    '',
    '> ' + REVIEW_NOTE,
    '',
  ];
  if (entries.length === 0) {
    lines.push('No findings were selected.', '');
    return lines.join('\n');
  }
  lines.push('## Contents', '', '| # | Severity | Title |', '| --- | --- | --- |');
  entries.forEach((entry, index) =>
    lines.push(
      '| ' +
        (index + 1) +
        ' | ' +
        entry.finding.severity +
        ' | ' +
        oneLine(entry.finding.title).replace(/\|/g, '\\|') +
        ' |',
    ),
  );
  entries.forEach((entry, index) => {
    lines.push(
      '',
      '## ' +
        (index + 1) +
        '. [' +
        entry.finding.severity.toUpperCase() +
        '] ' +
        oneLine(entry.finding.title),
      '',
      ...findingBody(entry),
    );
  });
  lines.push('');
  return lines.join('\n');
}

/** A short, safe file name part from a title. */
export function slug(title: string): string {
  const text = oneLine(title)
    .toLowerCase()
    .normalize('NFKD')
    .replace(/\p{M}+/gu, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 50)
    .replace(/-+$/g, '');
  return text === '' ? 'finding' : text;
}

export function githubIssueFiles(input: {
  readonly entries: readonly ExportedFinding[];
}): ExportFile[] {
  const files: ExportFile[] = [];
  const index: Array<Record<string, unknown>> = [];
  input.entries.forEach((entry, position) => {
    const name = String(position + 1).padStart(3, '0') + '-' + slug(entry.finding.title) + '.md';
    const path = 'issues/' + name;
    const body = ['Reported by Sentry. ' + REVIEW_NOTE, '', ...findingBody(entry), ''].join('\n');
    files.push({ path, content: body });
    index.push({
      file: path,
      title:
        '[' +
        entry.finding.severity.toUpperCase() +
        '] ' +
        oneLine(entry.finding.title).slice(0, 200),
      labels: [
        'bug',
        'sentry',
        'severity:' + entry.finding.severity,
        'category:' + entry.finding.category,
      ],
      severity: entry.finding.severity,
      findingId: entry.finding.id,
      runId: entry.runId,
    });
  });
  files.unshift({ path: 'issues.json', content: JSON.stringify(index, null, 2) + '\n' });
  files.unshift({
    path: 'README.md',
    content: [
      '# Sentry findings as GitHub issues',
      '',
      'This folder has ' +
        input.entries.length +
        ' issue body file(s) in `issues/` and `issues.json`,',
      'which lists the title and suggested labels of each one. Nothing here has been sent to GitHub.',
      '',
      '> ' + REVIEW_NOTE,
      '',
      'With the GitHub CLI, from a clone of the repository (create the labels first, or drop `--label`):',
      '',
      '```bash',
      'gh issue create --title "TITLE FROM issues.json" --body-file issues/001-example.md --label bug,sentry',
      '```',
      '',
      'Or paste the body of a file into a new issue on github.com.',
      '',
    ].join('\n'),
  });
  return files;
}

const SARIF_LEVEL: Record<string, string> = {
  critical: 'error',
  high: 'error',
  medium: 'warning',
  low: 'note',
  info: 'note',
};

export function sarifLog(input: {
  readonly entries: readonly ExportedFinding[];
  readonly toolVersion: string;
}): string {
  const categories = [...new Set(input.entries.map((entry) => entry.finding.category))].sort();
  const rules = categories.map((category) => ({
    id: 'sentry/' + category,
    name: category,
    shortDescription: { text: 'Sentry ' + category + ' finding' },
    properties: { tags: ['sentry', category] },
  }));
  const results = input.entries.map((entry) => {
    const { finding } = entry;
    return {
      ruleId: 'sentry/' + finding.category,
      ruleIndex: categories.indexOf(finding.category),
      level: SARIF_LEVEL[finding.severity] ?? 'warning',
      message: {
        text: (oneLine(finding.title) + ': ' + oneLine(finding.description)).slice(0, 4000),
      },
      locations: finding.locations.map((location) => ({
        physicalLocation: {
          artifactLocation: {
            uri: location.relativePath.split('/').map(encodeURIComponent).join('/'),
            uriBaseId: '%SRCROOT%',
          },
          ...(location.startLine === undefined
            ? {}
            : {
                region: {
                  startLine: location.startLine,
                  ...(location.endLine === undefined ? {} : { endLine: location.endLine }),
                },
              }),
        },
        ...(location.symbol === undefined
          ? {}
          : { logicalLocations: [{ name: oneLine(location.symbol) }] }),
      })),
      partialFingerprints: { 'sentryFindingId/v1': finding.id },
      properties: {
        severity: finding.severity,
        confidence: finding.confidence,
        category: finding.category,
        agent: finding.sourceAgentStackId,
        runId: entry.runId,
        revisionId: entry.revisionId ?? null,
        reproductionSteps: finding.reproductionSteps.map(oneLine),
      },
    };
  });
  const log = {
    $schema: 'https://json.schemastore.org/sarif-2.1.0.json',
    version: '2.1.0',
    runs: [
      {
        tool: {
          driver: {
            name: 'Sentry',
            version: input.toolVersion,
            informationUri: 'https://github.com/Mert1026/Sentry',
            rules,
          },
        },
        originalUriBaseIds: { '%SRCROOT%': { description: { text: 'The project root' } } },
        results,
      },
    ],
  };
  return JSON.stringify(log, null, 2) + '\n';
}

function severityRank(severity: string): number {
  const index = (SEVERITY_ORDER as readonly string[]).indexOf(severity);
  return index === -1 ? SEVERITY_ORDER.length : index;
}

/** Resolve the selection to stored findings, newest revision data included, in a stable order. */
export function collectFindingsForExport(
  repository: SentryRepository,
  projectId: string,
  selection: FindingExportSelection,
): ExportedFinding[] {
  const revisionOf = (runId: string): { id: string | undefined; hash: string | undefined } => {
    const run = repository.getRun(runId as never);
    const snapshot = run === undefined ? undefined : repository.getSnapshot(run.snapshotId);
    const id = snapshot?.projectRevisionId;
    return {
      id,
      hash: id === undefined ? undefined : repository.getRevision(id)?.contentHash,
    };
  };
  const evidenceFor = (runId: string, finding: Finding): Evidence[] => {
    const all = repository.listEvidence(runId as never);
    return finding.evidenceIds.flatMap((id) => all.filter((item) => item.id === id));
  };
  const entryFor = (runId: string, finding: Finding): ExportedFinding => {
    const revision = revisionOf(runId);
    return {
      finding,
      runId,
      revisionId: revision.id,
      revisionHash: revision.hash,
      evidence: evidenceFor(runId, finding),
    };
  };
  const requireRun = (runId: string) => {
    const run = repository.getRun(runId as never);
    if (run === undefined || run.projectId !== projectId)
      throw new RunEngineError('INVALID_TARGET', 'Run ' + runId + ' is not part of this project');
    return run;
  };

  let entries: ExportedFinding[];
  if ('findings' in selection) {
    if (selection.findings.length === 0)
      throw new RunEngineError('INVALID_TARGET', 'Select at least one finding to export.');
    if (selection.findings.length > FINDING_EXPORT_MAX_FINDINGS)
      throw new RunEngineError(
        'INVALID_TARGET',
        'An export takes at most ' + FINDING_EXPORT_MAX_FINDINGS + ' findings.',
      );
    const seen = new Set<string>();
    entries = selection.findings.map((ref) => {
      requireRun(ref.runId);
      const finding = repository
        .listFindings(ref.runId as never)
        .find((item) => item.id === ref.findingId);
      if (finding === undefined)
        throw new RunEngineError('INVALID_TARGET', 'Finding ' + ref.findingId + ' was not found');
      if (seen.has(finding.id))
        throw new RunEngineError('INVALID_TARGET', 'The same finding was listed twice.');
      seen.add(finding.id);
      return entryFor(ref.runId, finding);
    });
  } else if ('runId' in selection) {
    const run = requireRun(selection.runId);
    entries = repository.listFindings(run.id).map((finding) => entryFor(run.id, finding));
  } else {
    if (selection.revisionIds.length === 0)
      throw new RunEngineError('INVALID_TARGET', 'Name at least one revision to export.');
    const wanted = new Set(selection.revisionIds);
    entries = repository
      .listRuns(projectId as never)
      .filter((run) => run.executionKind === 'production')
      .filter((run) => wanted.has(revisionOf(run.id).id ?? ''))
      .flatMap((run) =>
        repository.listFindings(run.id).map((finding) => entryFor(run.id, finding)),
      );
  }
  if (entries.length > FINDING_EXPORT_MAX_FINDINGS)
    throw new RunEngineError(
      'INVALID_TARGET',
      'That selection has ' +
        entries.length +
        ' findings; an export takes at most ' +
        FINDING_EXPORT_MAX_FINDINGS +
        '. Select fewer.',
    );
  return sortFindings(entries);
}

/** Worst first, then oldest first, then by ID, so the same selection always gives the same files. */
export function sortFindings(entries: readonly ExportedFinding[]): ExportedFinding[] {
  return [...entries].sort(
    (a, b) =>
      severityRank(a.finding.severity) - severityRank(b.finding.severity) ||
      a.finding.createdAt.localeCompare(b.finding.createdAt) ||
      a.finding.id.localeCompare(b.finding.id),
  );
}

/** Build the files for a format from already resolved findings. */
export function buildFindingExport(input: {
  readonly format: FindingExportFormat;
  readonly projectName: string;
  readonly entries: readonly ExportedFinding[];
  readonly generatedAt: string;
  readonly toolVersion: string;
}): FindingExportResult {
  const sorted = sortFindings(input.entries);
  const ordered = { ...input, entries: sorted };
  let files: ExportFile[];
  let suggestedName: string;
  let mimeType: string;
  if (input.format === 'markdown') {
    files = [{ path: 'sentry-findings.md', content: markdownReport(ordered) }];
    suggestedName = 'sentry-findings.md';
    mimeType = 'text/markdown';
  } else if (input.format === 'sarif') {
    files = [{ path: 'sentry-findings.sarif', content: sarifLog(ordered) }];
    suggestedName = 'sentry-findings.sarif';
    mimeType = 'application/sarif+json';
  } else {
    files = githubIssueFiles(ordered);
    suggestedName = 'sentry-github-issues.zip';
    mimeType = 'application/zip';
  }
  const bytes = files.reduce((sum, file) => sum + Buffer.byteLength(file.content, 'utf8'), 0);
  if (bytes > FINDING_EXPORT_MAX_BYTES)
    throw new RunEngineError(
      'INVALID_TARGET',
      'That export is too large (' + bytes + ' bytes); select fewer findings.',
    );
  return {
    format: input.format,
    files,
    findingCount: input.entries.length,
    suggestedName,
    mimeType,
  };
}

/** Resolve a selection and build the export in one step. */
export function exportFindings(
  repository: SentryRepository,
  projectId: string,
  input: {
    readonly format: FindingExportFormat;
    readonly selection: FindingExportSelection;
    readonly toolVersion: string;
    readonly generatedAt: string;
  },
): FindingExportResult {
  const project = repository.getProject(projectId as never);
  if (project === undefined)
    throw new RunEngineError('PROJECT_NOT_FOUND', 'Project not found: ' + projectId);
  const entries = collectFindingsForExport(repository, projectId, input.selection);
  return buildFindingExport({
    format: input.format,
    projectName: project.name,
    entries,
    generatedAt: input.generatedAt,
    toolVersion: input.toolVersion,
  });
}
